function createTask(intent,title,parent=null){const existing=state.tasks.find(t=>t.intentId===intent.id);if(existing)return existing;const kind=intent.kind;const task={id:'DEMO-TASK-'+(++state.sequence),intentId:intent.id,kind,title:title.replace(/确认|提交/g,''),domain:intent.domain,actor:intent.role,epoch:intent.epoch,state:'queued',progress:0,attempt:0,safeReplay:['detection','export','health'].includes(kind),target:intent.target||null,template:intent.template||null,targets:intent.targets||null,exportType:intent.exportType||intent.dataSnapshot?.type||null,parent,scenario:intent.scenario,created:Date.now(),events:[{time:'00:00:00 UTC / 演示',text:'提交意图已记录，等待本地状态演示。'}],error:null,data:kind==='export'?structuredClone(intent.dataSnapshot||snapshotExport(intent.exportType||'assets',intent.domain)):null};state.tasks.unshift(task);audit('创建合成任务',task.id);return task;}
function snapshotExport(type,domain){if(type==='events')return {type,rows:state.events.filter(e=>e.domain===domain).map(e=>['SYNTHETIC',e.id,e.title,DOMAINS[e.domain],e.state]),headers:['classification','id','event','domain','state']};if(type==='audit')return {type,rows:visibleAudits().filter(a=>a.domain===domain).map(a=>['SYNTHETIC',a.action,a.target,a.result]),headers:['classification','action','target','result']};return {type,rows:ASSETS.filter(a=>a.domain===domain).map(a=>['SYNTHETIC',a.id,a.name,a.type,DOMAINS[a.domain],a.sid||'未观测']),headers:['classification','id','name','type','domain','sid']};}
function exportDialog(type){if(!canWrite()||!validScope()){toast('当前身份没有此范围的演示导出权限。');return;}const domain=selectedDomain();const data=snapshotExport(type,domain);const intent={id:'intent-'+(++state.sequence),kind:'export',exportType:type,dataSnapshot:structuredClone(data),domain,role:state.role,epoch:state.epoch,scenario:state.scenario,used:false};openDialog('创建合成导出',`<p>导出仅包含下列明确范围的合成字段。生成本地 CSV，不代表真实生产 XLSX、报告或完整源字段兼容。</p><div class="response-target"><div class="info-row"><span>导出域</span><strong>${DOMAINS[domain]}</strong></div><div class="info-row"><span>当前行数</span><strong>${data.rows.length}</strong></div><div class="info-row"><span>字段白名单</span><strong>${data.headers.join(', ')}</strong></div></div><p>下载时重新核验当前角色、授权版本与域范围；离开页面可从导出历史找回。</p>`,btn('创建导出任务','confirm-intent','primary'),()=>{if(intent.used)return;if(intent.epoch!==state.epoch||intent.role!==state.role||!domainAllowed(domain)||!canWrite()){closeDialog();toast('权限变化，原确认已失效。');return;}intent.used=true;createTask(intent,'合成 '+(type==='events'?'事件证据':type==='audit'?'操作审计':'目录资产')+'导出');closeDialog();setRoute('reports');toast('导出任务已记录，完成后可下载合成 CSV。');});pendingIntent=intent;}
function addDomain(){if(!canWrite())return;openDialog('添加演示域配置',`<p>不接收真实域地址或凭据。此向导只验证表单、用途分离与保存反馈，不创建生产连接。</p><label class="form-field"><span>合成域名称</span><input id="demo-domain-name" value="sandbox.example.test" maxlength="80" required><small>仅允许保留域 .example.test，无真实 DNS 查询。</small></label><label class="form-field"><span>凭据来源</span><select><option>未配置 · 稍后单独授权用途</option></select></label><label class="form-field"><span>传输</span><select><option>LDAPS · 验证证书（仅说明）</option></select></label><div id="domain-error" class="error-inline" role="alert"></div>`,btn('保存演示配置','confirm-intent','primary'),()=>{const val=$('#demo-domain-name').value.trim().toLowerCase();if(!/^[a-z][a-z0-9-]{0,30}\.example\.test$/.test(val)){$('#domain-error').textContent='请使用 label.example.test 形式的保留合成域。';$('#demo-domain-name').focus();return;}if(state.savedDomains.some(d=>d.name===val&&d.actor===state.role)){$('#domain-error').textContent='当前角色已保存同名演示配置。';return;}state.savedDomains.push({name:val,actor:state.role});audit('保存合成域配置',val);closeDialog();render();toast('演示配置已保存；未配置凭据，没有连接或自动授予域访问权。');});}
function directoryAuth(domain){if(!canWrite()||!domainAllowed(domain))return;const epoch=state.epoch;openDialog('演示目录 v2 用途授权',`<p>读取 v2 必须同时满足总开关、附加开关与独立用途授权。连接诊断授权不会自动升级。</p><div class="response-target">${DOMAINS[domain]} · DEMO-OP-01 · 仅显示引用</div><label class="check-label"><input id="directory-master" type="checkbox">ADTR_DIRECTORY_READ_ENABLED 总开关</label><label class="check-label"><input id="directory-v2" type="checkbox">ADTR_DIRECTORY_READ_V2_ENABLED 附加开关</label><label class="check-label"><input id="directory-grant" type="checkbox">当前角色的独立 v2 授权与凭据用途</label><div id="directory-error" class="error-inline" role="alert"></div>`,btn('演示读取合成目录','confirm-intent','primary'),()=>{if(epoch!==state.epoch||!domainAllowed(domain)){closeDialog();toast('权限或范围已变化。');return;}if(!['directory-master','directory-v2','directory-grant'].every(id=>$('#'+id).checked)){$('#directory-error').textContent='三个条件必须全部满足；旧用途不会自动升级。';return;}audit('演示目录用途核验',DOMAINS[domain]);closeDialog();state.domain=domain;setRoute('assets');toast('仅展示固定合成观测，没有修改任何生产开关。');});}
function cancelTask(id){const t=visibleTasks().find(t=>t.id===id);if(!t||!canWrite()||!['queued','running'].includes(t.state))return;if(t.state==='queued'){t.state='cancelled';t.events.push({time:'00:00:01 UTC / 演示',text:'尚未开始执行，排队任务取消已确认。'});audit('取消排队任务',t.id);}else{t.state='cancel_requested';t.cancelAt=Date.now();t.events.push({time:'00:00:03 UTC / 演示',text:'已记录取消请求，等待执行结束确认。'});audit('请求取消任务',t.id,'演示待确认');}render();toast(t.state==='cancelled'?'排队任务已取消，实际尝试仍为 0。':'已请求取消；停止等待不代表执行已经停止。');}
function recoverTask(id){const t=visibleTasks().find(t=>t.id===id);if(!t||t.state!=='failed'||!t.safeReplay||!canWrite())return;const epoch=state.epoch;openDialog('以新任务恢复',`<p>恢复保留旧任务历史，重新核验当前授权并创建关联父任务的新任务。不重置原记录。</p><div class="response-target">原任务：${t.id}<br>类型：${t.title}</div>`,btn('确认新建恢复任务','confirm-intent','primary'),()=>{if(epoch!==state.epoch||!domainAllowed(t.domain)||!canWrite()){closeDialog();toast('权限变化，恢复确认失效。');return;}const child=createTask({id:'recovery-'+t.id+'-'+state.epoch,kind:t.kind,domain:t.domain,role:state.role,epoch:state.epoch,scenario:'normal',template:t.template,targets:t.targets,exportType:t.exportType,dataSnapshot:t.data},t.title,t.id);closeDialog();setRoute('work');toast('恢复子任务 '+child.id+' 已创建。');});}
function reconcile(id){const t=visibleTasks().find(t=>t.id===id);if(!t||t.state!=='unknown'||!canWrite())return;if(t.epoch!==state.epoch){toast('旧授权版本已失效，不能核对或复活原任务。');return;}t.state='succeeded';t.progress=100;t.events.push({time:'00:00:08 UTC / 演示',text:'只读核对固定夹具确认原提交已完成；没有重新执行或创建任务。'});audit('核对原任务结果',t.id);render();toast('原任务结果已核对；没有重放写入。');}
