function captureFocus(){const el=document.activeElement;if(!el||el===document.body)return null;return {id:el.id||null,action:el.dataset?.action||null,target:el.dataset?.id||null,drawer:!!el.closest('.drawer'),scroll:$('.drawer')?.scrollTop||0};}function restoreFocus(s){if(!s)return;const root=s.drawer?$('.drawer'):document;if(!root)return;let el=s.id?$('#'+CSS.escape(s.id),root):s.action?$('[data-action="'+CSS.escape(s.action)+'"]'+(s.target?'[data-id="'+CSS.escape(s.target)+'"]':''),root):null;if(!el&&s.target)el=$('[data-action="task-detail"][data-id="'+CSS.escape(s.target)+'"]',root);el?.focus({preventScroll:true});if(s.drawer&&$('.drawer'))$('.drawer').scrollTop=s.scroll;}function updateTaskRegions(){const el=$('#task-table-region');if(el){const f=captureFocus();el.innerHTML=taskTable(visibleTasks());restoreFocus(f);}}
function tick(){let changed=false;const now=Date.now();for(const t of state.tasks){if(!['queued','running','cancel_requested'].includes(t.state))continue;if(t.actor!==state.role||t.epoch!==state.epoch){t.state='failed';t.error='authorization_changed：旧授权版本失效，重新授予也不会复活旧任务。';t.events.push({time:'00:00:02 UTC / 演示',text:'会话身份或授权版本变化，演示任务停止。'});changed=true;continue;}if(t.state==='queued'&&now-t.created>=1800){t.state='running';t.attempt=1;t.events.push({time:'00:00:02 UTC / 演示',text:'开始一次实际演示尝试；重复点击不增加 attempt。'});changed=true;}else if(t.state==='cancel_requested'&&now-t.cancelAt>=1400){if(t.scenario==='cancel-race'){t.state='succeeded';t.progress=100;t.events.push({time:'00:00:04 UTC / 演示',text:'completed-with-cancel-race：完成先于取消，保留真实合成终态。'});}else if(t.scenario==='cancel-lost'){t.state='failed';t.error='cancellation_unconfirmed：执行停止尚未确认，不能声称已取消。';t.events.push({time:'00:00:04 UTC / 演示',text:'执行器失联夹具：保留停止未确认状态。'});}else{t.state='cancelled';t.events.push({time:'00:00:04 UTC / 演示',text:'执行器返回的合成确认已收到，取消完成。'});}changed=true;}else if(t.state==='running'){t.progress=Math.min(95,Math.floor((now-t.created-1800)/55));changed=true;if(now-t.created>=7000){if(t.scenario==='unknown'){t.state='unknown';t.events.push({time:'00:00:07 UTC / 演示',text:'提交结果未确认，保留原意图；等待只读核对，不自动重放。'});}else if(t.scenario==='failed'){t.state='failed';t.error=t.safeReplay?'synthetic_transient_error：可手动重新授权，创建恢复子任务。':'synthetic_input_error：单次类型失败，不提供通用 recover。';t.events.push({time:'00:00:07 UTC / 演示',text:'明确的合成失败，没有真实外部副作用。'});}else if(t.scenario==='partial'&&t.kind==='detection'){t.state='partial_failed';t.objectResults=(t.targets||[]).map((o,i)=>({...o,state:['成功','失败','结果不确定'][i%3]}));t.events.push({time:'00:00:07 UTC / 演示',text:'冻结的检测对象成功/失败/不确定结果已保留；禁止整批恢复。'});}else if(t.scenario==='partial'){t.state='failed';t.error='synthetic_single_target_failure：部分失败场景仅适用于多对象检测。此任务仅报告已确认目标的合成失败，不产生额外对象。';t.events.push({time:'00:00:07 UTC / 演示',text:t.target?`已确认目标 ${t.target.name} / ${t.target.assetId} 合成失败；没有其他响应对象。`:'当前类型不适用多对象部分失败，保留明确失败。'});}else{t.state='succeeded';t.progress=100;t.events.push({time:'00:00:07 UTC / 演示',text:'合成任务已完成；不是实际 AD 或产品验收。'});}audit('合成任务终态',t.id,taskLabel(t));}}}if(changed){if(state.drawer?.type==='task'&&!stateGuard(state.route)){const f=captureFocus();$('.drawer-overlay')?.remove();renderDrawer();restoreFocus(f);}updateTaskRegions();if(state.route==='reports'&&!state.drawer&&!$('#dialog').open)render();}}
function switchContext(kind,value){closeDialog();state.drawer=null;if(kind==='role'||kind==='domain')state.responseTarget=null;state.filters={};if(kind==='role'){state.role=value;state.domain='all';state.epoch++;state.messagesRead.clear();}else if(kind==='domain'){state.domain=value;}else{state.scenario=value;}document.body.classList.remove('overlay-open');setRoute(state.route,true);toast('演示上下文已切换，旧选择、弹层与草稿已清除。');}
