function saveGrants(){if(!role().admin){toast('当前演示角色不能管理权限。');return;}const read=$('#grant-read').checked,write=$('#grant-write').checked;if(write&&!read){toast('写入依赖读取权限；请先启用读取。');$('#grant-read').focus();return;}const epoch=state.epoch;openDialog('确认演示权限变更',`<p>目标是另一自定义角色。不会修改当前操作者、真实用户或服务器权限。</p><div class="response-target"><div class="info-row"><span>响应读取</span><strong>${read?'允许':'拒绝'}</strong></div><div class="info-row"><span>响应写入</span><strong>${write?'允许':'拒绝'}</strong></div><div class="info-row"><span>显式资源组</span><strong>alpha.example.test</strong></div></div><label class="check-label"><input id="grant-proof" type="checkbox">已完成演示新鲜验证，理解受影响会话需撤销</label><div id="grant-error" class="error-inline" role="alert"></div>`,btn('保存演示变更','confirm-intent','primary'),()=>{if(epoch!==state.epoch||!role().admin){closeDialog();toast('权限变更确认失效。');return;}if(!$('#grant-proof').checked){$('#grant-error').textContent='请确认演示验证与会话撤销影响。';return;}state.roleGrant={read,write};audit('修改另一演示角色权限','DEMO-Response');closeDialog();render();toast('演示角色权限已保存；受影响角色会话撤销仅作说明，不涉及真实身份。');});}
