'add-domain':addDomain,'directory-auth':el=>directoryAuth(el.dataset.domain),'diagnose':el=>{if(!domainAllowed(el.dataset.domain))return;state.domain=el.dataset.domain;confirmation('diagnostic','单次连接诊断','<div class="info-row"><span>尝试上限</span><strong>1 · 无通用恢复</strong></div>');},
