'response-confirm':()=>confirmation('response','账户访问限制演示','<div class="info-row"><span>目标</span><strong>当前域的明确合成对象 · 1 项</strong></div><div class="info-row"><span>目标版本</span><strong>v3 · 仅演示</strong></div>'),
'export-assets':()=>exportDialog('assets'),'export-events':()=>exportDialog('events'),'export-audit':()=>exportDialog('audit'),'export-overview':()=>exportDialog('assets'),
'health-task':()=>confirmation('health','基础设施健康演示'),
'cancel-task':el=>cancelTask(el.dataset.id),'recover-task':el=>recoverTask(el.dataset.id),'reconcile-task':el=>reconcile(el.dataset.id),'download-task':el=>download(el.dataset.id),
