'event-investigate':el=>{const e=visibleEvents().find(e=>e.id===el.dataset.id);if(e&&canWrite()){e.state='调查中';audit('标记合成事件',e.id);render();toast('事件已标为调查中。');}},
'event-close':el=>{const e=visibleEvents().find(e=>e.id===el.dataset.id);if(!e||!canWrite())return;const epoch=state.epoch;openDialog('关闭合成事件',`<p>${e.title}</p><p>关闭只改变演示事件处理状态，不执行阻断，不删除证据。当前目标：${DOMAINS[e.domain]} / ${e.id}。</p>`,btn('确认关闭事件','confirm-intent','primary'),()=>{if(epoch!==state.epoch||!domainAllowed(e.domain)){closeDialog();toast('范围已变化。');return;}e.state='已关闭';audit('关闭合成事件',e.id);closeDialog();render();});},
'event-response':el=>{const e=visibleEvents().find(e=>e.id===el.dataset.id);if(!e||!canWrite())return;state.domain=e.domain;state.responseTarget=Object.freeze({eventId:e.id,assetId:e.asset,version:3});setRoute('response');},
'work-tab':el=>{state.tab.work=el.dataset.tab;render();},'admin-tab':el=>{state.tab.admin=el.dataset.tab;render();},
'messages':()=>{state.tab.work='messages';setRoute('work');},'mark-read':el=>{if(visibleEvents().some(e=>e.id===el.dataset.id)){state.messagesRead.add(el.dataset.id);render();}},
'coverage-page':el=>showCoverage(el.dataset.page),'coverage-all':()=>showCoverage(),
'save-grants':saveGrants,
